import json


def load_config(path):
    with open(path, 'r', encoding='utf-8') as f:
        config = json.load(f)

    required_fields = ['name', 'version']
    for field in required_fields:
        if field not in config:
            raise ValueError(f"Missing required field: {field}")

    return config


